[
  {
    "id": "[1]",
    "speaker_to_listener": "Carlos→Leon",
    "self_ref": "ta",
    "addr_ref": "cậu",
    "dst": "“Nhắc đến pudding thì…… Ồ, món tráng miệng với kết cấu mềm mịn kỳ lạ đó sao? Công nhận là món đó rất ngon. Nhưng mà, nó không để được lâu đúng không?”"
  },
  {
    "id": "[2]",
    "speaker_to_listener": "Leon→Carlos",
    "self_ref": "tôi",
    "addr_ref": "ông",
    "dst": "“Ể? À, đúng là vậy ạ.”"
  },
  {
    "id": "[3]",
    "dst": "Bỏ vào tủ lạnh thì tối đa cũng chỉ được mấy ngày. Ở thế giới này thì bảo quản ở nhiệt độ phòng là bình thường, nên một ngày là kịch kim rồi thế nhưng…… sao ông ấy lại biết chuyện đó nhỉ?"
  },
  {
    "id": "[4]",
    "speaker_to_listener": "Carlos→Leon",
    "self_ref": "ta",
    "addr_ref": "cậu",
    "dst": "“Thực ra ta đã cho người tìm hiểu đủ điều vì định mang đi bán đấy. Nhưng vì không để được lâu nên ta đành bỏ cuộc.”"
  },
  {
    "id": "[5]",
    "speaker_to_listener": "Leon→Carlos",
    "self_ref": "tôi",
    "addr_ref": "ông",
    "dst": "“Hóa ra là vậy……”"
  },
  {
    "id": "[6]",
    "dst": "Hay nói đúng hơn là, chú ấy đã định bán nó sao? Không, dù sao thì cũng chẳng phải do tôi phát minh ra, với lại ở thế giới này cũng chẳng có vụ đăng ký sản phẩm gì sất nên chẳng vấn đề gì cả…… Mà thế nào cũng được."
  },
  {
    "id": "[7]",
    "speaker_to_listener": "Leon→Carlos",
    "self_ref": "tôi",
    "addr_ref": "ông",
    "dst": "“Pudding thì không để được lâu, nhưng tôi biết công thức của một số loại bánh ngọt để được lâu đấy ạ. Vì thế, tôi nghĩ bán những loại đó thì sẽ ổn hơn. Hơn nữa, kể cả với những món bánh không để được lâu, nếu mở cửa hàng ở những thành phố lớn thì chắc chắn vẫn bán được.”"
  },
  {
    "id": "[8]",
    "speaker_to_listener": "Carlos→Leon",
    "self_ref": "ta",
    "addr_ref": "cậu",
    "dst": "“Hừm. Nếu mọi điều cậu nói đều là sự thật, thì chúng ta sẽ thu về được một đặc quyền khổng lồ đấy chứ……ả?”"
  },
  {
    "id": "[9]",
    "dst": "Carlos im lặng như để ngẫm lại nội dung vừa nghe. Sau một thoáng chốc, ông hướng ánh mắt về phía Regis đang đứng nghe nãy giờ."
  },
  {
    "id": "[10]",
    "speaker_to_listener": "Carlos→Regis",
    "self_ref": "tôi",
    "addr_ref": "ông",
    "dst": "“Nghe câu chuyện vừa rồi, ông nghĩ thế nào?”"
  },
  {
    "id": "[11]",
    "speaker_to_listener": "Regis→Carlos",
    "self_ref": "tôi",
    "addr_ref": "thiếu gia",
    "dst": "“Tôi không có kiến thức về nội chính nên không dám đưa ra câu trả lời. Thế nhưng…… tiểu thư Sophia hoàn toàn đặt trọn niềm tin vào thiếu gia Leon ạ.”"
  },
  {
    "id": "[12]",
    "speaker_to_listener": "Carlos→Regis",
    "self_ref": "ta",
    "addr_ref": "ông",
    "dst": "“……Là Sophia sao.”"
  },
  {
    "id": "[13]",
    "dst": "Ồ, đây là một diễn biến thuận lợi đây. Trước sự tín nhiệm của Sophia thì mọi ác ý đều không thể che giấu được, thế nên đây chắc chắn là bằng chứng rõ ràng nhất cho thấy tôi không hề nói dối."
  },
  {
    "id": "[14]",
    "dst": "Có vẻ Carlos cũng nghĩ như vậy, thái độ của ông đã dịu đi."
  },
  {
    "id": "[15]",
    "speaker_to_listener": "Carlos→Leon",
    "self_ref": "ta",
    "addr_ref": "cậu",
    "dst": "“Leon này. Ta muốn xác nhận lại một chút, có phải ý cậu là muốn giao toàn bộ chuyện này cho nhà ta đứng ra quản lý phải không?”"
  },
  {
    "id": "[16]",
    "speaker_to_listener": "Leon→Carlos",
    "self_ref": "tôi",
    "addr_ref": "ông",
    "dst": "“Đương nhiên rồi ạ. Từ nhân lực cho đến vốn liếng, thực tế chúng tôi đều phải dựa dẫm vào gia tộc Sfeel, nên tôi không có ý kiến gì miễn là đảm bảo được sự tự do cho phe mình.”"
  },
  {
    "id": "[17]",
    "speaker_to_listener": "Carlos→Leon",
    "self_ref": "ta",
    "addr_ref": "cậu",
    "dst": "“Hừm. Vậy ta hỏi xác nhận thêm một điều nữa nhé. Cậu vừa nói là đang khao khát sự tự do đúng chứ? Nói cách khác, có phải ý cậu là không muốn kết hôn với Sophia không?”"
  },
  {
    "id": "[18]",
    "dst": "Ứ hự. Đ, đúng rồi nhỉ. Dù có nói với Sophia đi chăng nữa, mà không thông qua Carlos thì cũng công cốc. Tôi chưa kịp nghĩ ra lời bào chữa nào cả, tình huống này căng thật đấy!"
  },
  {
    "id": "[19]",
    "speaker_to_listener": "Leon→Carlos",
    "self_ref": "tôi",
    "addr_ref": "ông",
    "dst": "“Ờ thì, chuyện đó là thế này. Ấy là……”"
  },
  {
    "id": "[20]",
    "speaker_to_listener": "Carlos→Leon",
    "self_ref": "ta",
    "addr_ref": "cậu",
    "dst": "“……Ý cậu không phải là ghét Sophia chứ?”"
  },
  {
    "id": "[21]",
    "speaker_to_listener": "Leon→Carlos",
    "self_ref": "tôi",
    "addr_ref": "ông",
    "dst": "“Đương nhiên là không rồi ạ! Sophia là một cô bé cực kỳ tốt bụng và ở cùng em ấy rất vui. Chỉ là, cả hai chúng tôi vẫn còn nhỏ nên hiện tại chưa thể nghĩ đến chuyện đó được hay nói cách khác là……”"
  },
  {
    "id": "[22]",
    "speaker_to_listener": "Carlos→Leon",
    "self_ref": "ta",
    "addr_ref": "cậu",
    "dst": "“Ra vậy. Nếu thế thì đổi thành hình thức nhận nuôi thì cậu không có ý kiến gì đúng chứ?”"
  },
  {
    "id": "[23]",
    "speaker_to_listener": "Leon→Carlos",
    "self_ref": "tôi",
    "addr_ref": "ông",
    "dst": "“Ể, ề…… Tôi thì sao cũng được nhưng mà……”"
  },
  {
    "id": "[24]",
    "speaker_to_listener": "Carlos→Leon",
    "self_ref": "ta",
    "addr_ref": "cậu",
    "dst": "“Tốt lắm, ta hiểu rồi. Vậy chúng ta cứ tiến hành theo hướng đó nhé.”"
  },
  {
    "id": "[25]",
    "dst": "Ể, có thể dễ dàng đồng ý nhanh gọn thế sao? ……Hả, thật á?"
  },
  {
    "id": "[26]",
    "speaker_to_listener": "Carlos→Leon",
    "self_ref": "ta",
    "addr_ref": "cậu",
    "dst": "“Vậy, về các điều khoản chi tiết thì……”"
  },
  {
    "id": "[27]",
    "dst": "Bỏ ngoài tai những lo lắng của tôi, cuộc thảo luận cứ thế tiến triển một cách suôn sẻ đến bất ngờ."
  },
  {
    "id": "[28]",
    "dst": "Cứ thế, buổi trao đổi với Carlos kết thúc trong chớp mắt. Vui mừng vì từ nay chúng tôi đã có được sự tự do, tôi hân hoan trở về dinh thự của gia tộc Granches thế nhưng――"
  },
  {
    "id": "[29]",
    "speaker_to_listener": "Caroline→Leon",
    "self_ref": "ta",
    "addr_ref": "cậu",
    "dst": "“――Leon, ta sẽ giam lỏng cậu.”"
  },
  {
    "id": "[30]",
    "dst": "Thứ đang chờ đợi tôi ở nhà chính là câu nói vô tình tàn nhẫn của bà Caroline."
  }
]

[
  {
    "id": "[1]",
    "speaker_to_listener": "Claire→Leon",
    "self_ref": "chị",
    "addr_ref": "em",
    "dst": "“Chị không đời nào lại mang chuyện đó ra đùa vào lúc thế này đâu.”"
