  {
    "id": "[6]",
    "speaker_to_listener": "Leon→Claire",
    "self_ref": "tôi",
    "addr_ref": "chị",
    "dst": "“……Chị Claire thích tôi sao?”"
  },
  {
    "id": "[7]",
    "speaker_to_listener": "Claire→Leon",
    "self_ref": "chị",
    "addr_ref": "em",
    "dst": "“Đúng vậy. Chị bị thu hút bởi em như một người con trai.”"
  },
  {
    "id": "[8]",
    "dst": "Là thật lòng sao? Ý cậu ta là ngay cả những lời tỏ tình thoạt nghe như đùa cợt trước giờ cũng đều là thật lòng cả ư? Chị Claire thực sự muốn dâng hiến lần đầu tiên của mình cho tôi? Vả lại,"
  },
  {
    "id": "[9]",
    "dst": "Nếu là vậy, tôi nên làm thế nào đây?"
  },
  {
    "id": "[10]",
    "dst": "Với một kẻ mang ký ức kiếp trước như tôi, bản thân tôi chính là Yuya, còn Leon chỉ là cái tên của cơ thể mới có được này mà thôi. Chính vì thế, cảm giác chị Claire – người từng sống ở một nơi khác – là chị ruột thịt của mình vốn rất nhạt nhòa."
  },
  {
    "id": "[11]",
    "dst": "Thế nên, nếu bảo rằng tôi chưa từng coi chị ấy như một người khác giới thì chắc chắn là dối lòng."
  },
  {
    "id": "[12]",
    "dst": "Nhưng mà, nói là nói thế. Việc thỉnh thoảng cảm thấy xao xuyến khi nhìn thấy chị gái với việc có thể xem chị ấy như đối tượng hẹn hò là hai chuyện hoàn toàn khác nhau phải không? Ít nhất thì tôi không thể nhìn chị Claire theo chiều hướng đó được."
  },
  {
    "id": "[13]",
    "dst": "Chính vì thế, tôi không thể chấp nhận tình cảm của chị Claire."
  },
  {
    "id": "[14]",
    "dst": "Dù nghĩ vậy, trong lòng tôi vẫn có một gợn sóng lăn tăn. Đó là việc tôi có lẽ sẽ chẳng bao giờ được gặp lại chị Claire nữa. Nếu làm tổn thương chị Claire ở đây, biết đâu tôi sẽ lại hối hận hệt như lúc đánh mất Sāya."
  },
  {
    "id": "[15]",
    "dst": "Giữa lúc tôi đang chìm trong ngõ cụt của suy nghĩ, lòng bàn tay chị Claire áp lên gò má tôi."
  },
  {
    "id": "[16]",
    "speaker_to_listener": "Claire→Leon",
    "self_ref": "chị",
    "addr_ref": "em",
    "dst": "“——Chị rất thích em, em trai ngoan.”"
  },
  {
    "id": "[17]",
    "dst": "Đôi môi chị Claire sượt qua má tôi và thì thầm bên tai. Nói xong, chị Claire lập tức đứng dậy."
  },
  {
    "id": "[18]",
    "speaker_to_listener": "Leon→Claire",
    "self_ref": "tôi",
    "addr_ref": "chị",
    "dst": "“……Chị Claire?”"
  },
  {
    "id": "[19]",
    "speaker_to_listener": "Claire→Leon",
    "self_ref": "chị",
    "addr_ref": "em",
    "dst": "“Xin lỗi nhé, chị phải đi đây. Chị không còn nhiều thời gian nữa đâu.”"
  },
  {
    "id": "[20]",
    "speaker_to_listener": "Leon→Claire",
    "self_ref": "tôi",
    "addr_ref": "chị",
    "dst": "“Ơ, nhưng mà——”"
  },
  {
    "id": "[21]",
    "dst": "Nếu định dâng hiến lần đầu tiên cho tôi, lẽ ra chị ấy phải còn chút thời gian chứ——nghĩ đến đây, nhìn thấy vẻ mặt đượm buồn của chị Claire, tôi liền thấu hiểu tất cả."
  },
  {
    "id": "[22]",
    "dst": "Ngay từ đầu, chị Claire đã nói rằng mình không còn nhiều thời gian. Chị Claire chỉ muốn tôi đón nhận tình cảm của mình mà thôi."
  },
  {
    "id": "[23]",
    "dst": "Tôi lại sắp lặp lại sai lầm y như hồi Sāya rồi——"
  },
  {
    "id": "[24]",
    "speaker_to_listener": "Leon→Claire",
    "self_ref": "tôi",
    "addr_ref": "chị",
    "dst": "“Chị Claire!”"
  },
  {
    "id": "[25]",
    "speaker_to_listener": "Claire→Leon",
    "self_ref": "chị",
    "addr_ref": "em",
    "dst": "“……Tạm biệt nhé, em trai.”"
  },
  {
    "id": "[26]",
    "dst": "Bàn tay tôi vươn ra đã chẳng chạm tới được chị Claire. Chị Claire né tránh tay tôi và cứ thế bước ra khỏi phòng."
