  {
    "id": "[8]",
    "speaker_to_listener": "Regis→Leon",
    "self_ref": "tôi",
    "addr_ref": "thiếu gia",
    "dst": "“Hô, tốc độ phản ứng tuyệt vời thật đấy! Nhưng tiếc quá. Cơ thể đó không đủ sức rồi!”"
