  {
    "id": "[14]",
    "speaker_to_listener": "Regis→Leon",
    "self_ref": "tôi",
    "addr_ref": "thiếu gia",
    "dst": "“Tôi không thể hé lộ gì hơn. Nhưng tôi xin phép được nói điều này, chúng tôi sẽ không đối xử tệ với thiếu gia đâu.”"
  },
  {
    "id": "[15]",
    "speaker_to_listener": "Leon→Regis",
    "self_ref": "tôi",
    "addr_ref": "ông",
    "dst": "“……Không đối xử tệ, mày nói thật chứ?”"
  },
  {
    "id": "[16]",
    "dst": "Tôi liếc mắt ra sau lưng Regis. Nơi đó là thi thể của Blake."
  },
  {
    "id": "[17]",
    "dst": "Và trong đầu tôi hằn in khung cảnh thảm thương của những người trong gia tộc Granches, khởi đầu là cha và bà Caroline. Chẳng đời nào tôi lại đi tin lời Regis."
  },
